package org.marketreview.nativeapp;
import android.content.ContentValues;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.json.*;
final class DataSafetyStore {
 final File file;
 DataSafetyStore(File file)throws Exception{DataSafetyModel.require(file!=null&&file.isAbsolute(),"安全模块库须为绝对路径");this.file=file;File dir=file.getParentFile();DataSafetyModel.require(dir.isDirectory()||dir.mkdirs(),"安全模块库目录不可用");try(SQLiteDatabase db=open()){db.beginTransaction();try{int v=db.getVersion(),a=scalar(db,"PRAGMA application_id");if(v==0&&a==0){DataSafetyModel.require(scalar(db,"SELECT count(*) FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' AND name!='android_metadata'")==0,"目标非空，不重建");try(Cursor c=db.rawQuery("PRAGMA table_info(android_metadata)",null)){if(c.moveToFirst())DataSafetyModel.require(c.getInt(0)==0&&c.getString(1).equals("locale")&&c.getString(2).equalsIgnoreCase("TEXT")&&c.getInt(3)==0&&c.isNull(4)&&c.getInt(5)==0&&!c.moveToNext(),"系统元数据结构不兼容");}db.execSQL("CREATE TABLE records(kind TEXT PRIMARY KEY NOT NULL,revision TEXT NOT NULL,payload TEXT NOT NULL)");db.execSQL("CREATE TABLE source(id TEXT PRIMARY KEY NOT NULL,payload BLOB NOT NULL)");db.execSQL("PRAGMA application_id="+0x44534631);db.setVersion(1);}else DataSafetyModel.require(v==1&&a==0x44534631,"安全模块库身份/版本不支持，不重建");try(Cursor c=db.rawQuery("SELECT kind,revision,payload FROM records LIMIT 0",null);Cursor s=db.rawQuery("SELECT id,payload FROM source LIMIT 0",null)){c.moveToFirst();s.moveToFirst();}db.setTransactionSuccessful();}finally{db.endTransaction();}}}
 SQLiteDatabase open(){return SQLiteDatabase.openDatabase(file.getPath(),null,SQLiteDatabase.CREATE_IF_NECESSARY);}
 static int scalar(SQLiteDatabase db,String sql){try(Cursor c=db.rawQuery(sql,null)){DataSafetyModel.require(c.moveToFirst(),"安全模块查询失败");return c.getInt(0);}}
 static void allowed(String kind){DataSafetyModel.require(Arrays.asList("policy","drafts","stages","diagnostics").contains(kind),"未知安全模块记录类型");}
 static JSONObject get(SQLiteDatabase db,String kind)throws Exception{int chars,bytes;String revision;try(Cursor c=db.rawQuery("SELECT revision,length(payload),length(CAST(payload AS BLOB)) FROM records WHERE kind=?",new String[]{kind})){if(!c.moveToFirst())return new JSONObject();revision=c.getString(0);chars=c.getInt(1);bytes=c.getInt(2);}DataSafetyModel.require(bytes<=SourceAnalysisPacket.BYTE_LIMIT,"安全模块记录超过25MiB");StringBuilder body=new StringBuilder(chars);for(int start=1;start<=chars;start+=131072)try(Cursor c=db.rawQuery("SELECT substr(payload,?,131072) FROM records WHERE kind=?",new String[]{Integer.toString(start),kind})){DataSafetyModel.require(c.moveToFirst(),"读取期间记录改变");body.append(c.getString(0));}return new JSONObject().put("recordRevision",revision).put("data",new JSONObject(body.toString()));}
 static String write(SQLiteDatabase db,String kind,JSONObject data,String expected)throws Exception{allowed(kind);if(kind.equals("policy"))DataSafetyModel.policy(data);if(kind.equals("drafts"))DataSafetyModel.safeDraft(data.optString("input"));String payload=DataSafetyModel.json(data);DataSafetyModel.require(get(db,kind).optString("recordRevision").equals(expected),"另一入口已更新，未覆盖旧草稿；请明确重读");String rev=UUID.randomUUID().toString();ContentValues row=new ContentValues();row.put("kind",kind);row.put("revision",rev);row.put("payload",payload);db.delete("records","kind=?",new String[]{kind});db.insertOrThrow("records",null,row);return rev;}
 JSONObject get(String kind)throws Exception{allowed(kind);try(SQLiteDatabase db=open()){db.beginTransaction();try{JSONObject row=get(db,kind);db.setTransactionSuccessful();return row;}finally{db.endTransaction();}}}
 JSONObject settings()throws Exception{JSONObject row=get("policy");return row.length()==0?DataSafetyModel.defaults():DataSafetyModel.policy(row.getJSONObject("data"));}
 JSONObject put(String kind,JSONObject data,String expected)throws Exception{try(SQLiteDatabase db=open()){db.beginTransaction();try{String rev=write(db,kind,data,expected);if(kind.equals("stages"))db.delete("source",null,null);db.setTransactionSuccessful();return new JSONObject().put("recordRevision",rev).put("data",data);}finally{db.endTransaction();}}}
 JSONObject stage(JSONObject plan,byte[] source,String expected)throws Exception{DataSafetyModel.require(source.length<=SourceAnalysisPacket.BYTE_LIMIT&&plan.optString("sourceSha256").equals(DataSafetyModel.sha(source)),"计划与原始字节不一致");JSONObject summary=DataSafetyModel.summary(plan);JSONObject data=new JSONObject().put("plan",summary);try(SQLiteDatabase db=open()){db.beginTransaction();try{String rev=write(db,"stages",data,expected);db.delete("source",null,null);ContentValues row=new ContentValues();row.put("id","pending");row.put("payload",source);db.insertOrThrow("source",null,row);db.setTransactionSuccessful();return new JSONObject().put("recordRevision",rev).put("data",data);}finally{db.endTransaction();}}}
 byte[] source(String expected)throws Exception{try(SQLiteDatabase db=open()){db.beginTransaction();try{DataSafetyModel.require(get(db,"stages").optString("recordRevision").equals(expected),"预览被另一入口更新，请重读");int bytes;try(Cursor c=db.rawQuery("SELECT length(payload) FROM source WHERE id='pending'",null)){DataSafetyModel.require(c.moveToFirst(),"所选备份原文缺失");bytes=c.getInt(0);}DataSafetyModel.require(bytes<=SourceAnalysisPacket.BYTE_LIMIT,"原始备份超过25MiB");ByteArrayOutputStream out=new ByteArrayOutputStream(bytes);for(int start=1;start<=bytes;start+=131072)try(Cursor c=db.rawQuery("SELECT substr(payload,?,131072) FROM source WHERE id='pending'",new String[]{Integer.toString(start)})){DataSafetyModel.require(c.moveToFirst(),"读取期间原文改变");out.write(c.getBlob(0));}db.setTransactionSuccessful();return out.toByteArray();}finally{db.endTransaction();}}}
}

